"use client";
import { useCallback } from "react";
function useSubmitHandler(sendMessage, uploadFile, options = {}) {
  const { onUploadError, continueOnUploadError } = options;
  return useCallback(
    async (message) => {
      const text = message.text.trim();
      const files = message.files || [];
      if (!text && files.length === 0) return;
      if (files.length > 0 && uploadFile) {
        const parts = [];
        if (text) parts.push({ type: "text", text });
        const keepGoing = continueOnUploadError ?? !!onUploadError;
        for (const f of files) {
          const name = f.filename || "upload";
          try {
            const res = await fetch(f.url);
            if (!res.ok) {
              throw new Error(
                `Failed to read attachment "${name}": ${res.status} ${res.statusText}`
              );
            }
            const blob = await res.blob();
            await uploadFile("workspace", blob, name);
            parts.push({ type: "file", file_id: `workspace/${name}` });
          } catch (err) {
            if (onUploadError) {
              onUploadError(err, f);
            }
            if (!keepGoing) {
              throw err;
            }
          }
        }
        if (parts.length > 0) await sendMessage(parts);
      } else {
        await sendMessage(text);
      }
    },
    [sendMessage, uploadFile, onUploadError, continueOnUploadError]
  );
}
export {
  useSubmitHandler
};
